import {CoreStore} from './store';import {OpportunityRegistry,YieldRanker,CurrentPredicamentEngine,ThresholdEngine,EarningTaskQueue,FleetEngine,StrategySignalBus} from './engines';import {SupabaseMirror} from './supabase';
export class Runtime{store=new CoreStore();mirror=new SupabaseMirror();registry=new OpportunityRegistry(this.store);ranker=new YieldRanker();predicament=new CurrentPredicamentEngine();threshold=new ThresholdEngine();queue=new EarningTaskQueue(this.store);fleet=new FleetEngine(this.store);signals=new StrategySignalBus(this.store);async persist(){if(this.mirror.enabled)await this.mirror.snapshot(this.store.get())}async autopilot(){const s=this.store.get();const ranked=this.ranker.rank(s.opportunities.filter(o=>o.status==='ESTIMATED'));const capital=s.allocations.filter(a=>a.status==='EXECUTED').reduce((n,a)=>n+Number(a.amountSol),0);const zeroCapital=s.opportunities.filter(o=>o.capitalRequiredSol===0&&o.status==='ESTIMATED');const eligible=ranked.filter(o=>this.threshold.eligible(o,capital));for(const o of eligible.slice(0,20)){const strategy=s.strategies.find(x=>x.id===o.strategyId);if(!strategy)continue;const agents=s.agents.filter(a=>this.fleet.canEvaluate(a,o,strategy));if(!agents.length)continue;const origin=agents[0];this.signals.publish(o.id,origin.id,agents.map(a=>a.id));for(const agent of agents.slice(0,20))this.queue.enqueue(o,agent)}return {ranked,capital,threshold:this.predicament.state(capital),zeroCapitalOpportunities:zeroCapital.length,queuedAgents:eligible.map(o=>({opportunityId:o.id,agents:s.agents.filter(a=>a.status==='ACTIVE').map(a=>a.id)}))}}}
