import type {CoreState} from './store';
export class SupabaseMirror{
 readonly enabled=Boolean(process.env.SUPABASE_URL&&process.env.SUPABASE_SERVICE_ROLE_KEY);private base='';private key='';
 constructor(){this.base=(process.env.SUPABASE_URL||'').replace(/\/$/,'');this.key=process.env.SUPABASE_SERVICE_ROLE_KEY||''}
 private async upsert(table:string,rows:any[]){if(!rows.length)return;const r=await fetch(`${this.base}/rest/v1/${table}`,{method:'POST',headers:{apikey:this.key,Authorization:`Bearer ${this.key}`,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(rows)});if(!r.ok)throw new Error(`Supabase ${table} sync failed: ${r.status}`)}
 async snapshot(s:CoreState){if(!this.enabled)return;await this.upsert('agents',s.agents.map(x=>({id:x.id,wallet_address:x.walletAddress,strategy_permissions:x.strategyPermissions,budget_sol:x.budgetSol,risk_profile:x.riskProfile,supported_networks:x.supportedNetworks,minimum_expected_return_pct:x.minimumExpectedReturnPct,gas_reserve_sol:x.gasReserveSol,daily_loss_limit_sol:x.dailyLossLimitSol,exposure_limit_sol:x.exposureLimitSol,performance:x.performance,status:x.status,heartbeat:x.heartbeat,independent_decision_id:x.independentDecisionId})));await this.upsert('strategies',s.strategies.map(x=>({id:x.id,name:x.name,category:x.category,capital_required_sol:x.capitalRequiredSol,min_expected_return_pct:x.minExpectedReturnPct,risk_level:x.riskLevel,supports_zero_capital:x.supportsZeroCapital,enabled:x.enabled,description:x.description})));await this.upsert('opportunities',s.opportunities.map(x=>({id:x.id,strategy_id:x.strategyId,title:x.title,source:x.source,discovered_at:x.discoveredAt,expires_at:x.expiresAt,expected_gross_sol:x.expectedGrossSol,network_fees_sol:x.networkFeesSol,trading_fees_sol:x.tradingFeesSol,slippage_sol:x.slippageSol,risk_cost_sol:x.riskCostSol,capital_cost_sol:x.capitalCostSol,score_sol:x.scoreSol,status:x.status,capital_required_sol:x.capitalRequiredSol,evidence_url:x.evidenceUrl,metadata:x.metadata})));await this.upsert('signals',s.signals.map(x=>({id:x.id,opportunity_id:x.opportunityId,created_at:x.createdAt,expires_at:x.expiresAt,origin_agent_id:x.originAgentId,shared_with:x.sharedWith,independent_required:true})));await this.upsert('tasks',s.tasks.map(x=>({id:x.id,opportunity_id:x.opportunityId,agent_id:x.agentId,stage:x.stage,status:x.status,idempotency_key:x.idempotencyKey,created_at:x.createdAt,updated_at:x.updatedAt,reason:x.reason})));await this.upsert('allocations',s.allocations.map(x=>({id:x.id,bucket:x.bucket,amount_sol:x.amountSol,agent_id:x.agentId,strategy_id:x.strategyId,status:x.status,created_at:x.createdAt})));await this.upsert('revenue',s.revenue.map(x=>({id:x.id,source:x.source,external_id:x.externalId,recipient:x.recipient,asset:x.asset,amount:x.amount,network:x.network,timestamp:x.timestamp,signature:x.signature,status:x.status,idempotency_key:x.idempotencyKey,evidence:x.evidence,created_at:x.createdAt})));await this.upsert('transactions',s.transactions.map(x=>({id:x.id,kind:x.kind,state:x.state,signature:x.signature,created_at:x.createdAt,updated_at:x.updatedAt,idempotency_key:x.idempotencyKey,amount_sol:x.amountSol,destination:x.destination,error:x.error})));await this.upsert('risk_events',s.riskEvents.map(x=>({id:x.id,type:x.type,severity:x.severity,message:x.message,created_at:x.createdAt,entity_id:x.entityId})));await this.upsert('audit_logs',s.audit.map(x=>({id:x.id,at:x.at,action:x.action,actor:x.actor,entity_type:x.entityType,entity_id:x.entityId,result:x.result,metadata:x.metadata})))}
}
