import crypto from 'node:crypto';import type {TxRecord} from '../core/domain';import {CoreStore} from '../core/store';import {SolanaProviderManager} from '../solana/provider';
export class TreasuryAuthorizationService{
 constructor(private store:CoreStore,private provider:SolanaProviderManager){}
 async createTransferIntent(destination:string,amountSol:string,idempotencyKey:string){if(this.store.get().system.emergencyStop)throw new Error('Emergency stop engaged');if(!idempotencyKey)throw new Error('Idempotency key is required');if(this.store.get().transactions.some(x=>x.idempotencyKey===idempotencyKey))return this.store.get().transactions.find(x=>x.idempotencyKey===idempotencyKey)!;const from=process.env.TREASURY_VAULT_ADDRESS||process.env.WATCH_WALLET;if(!from)throw new Error('TREASURY_VAULT_ADDRESS or WATCH_WALLET is required');const tx:TxRecord={id:crypto.randomUUID(),kind:'TRANSFER_INTENT',state:'REQUEST',createdAt:Date.now(),updatedAt:Date.now(),idempotencyKey,amountSol,destination};this.store.addTx(tx);this.store.audit('transfer_intent_created','system','transaction',tx.id,'PENDING',{destination,amountSol});this.store.updateTx(tx.id,{state:'VALIDATE'});const state=await this.provider.validateTransferIntent(from,destination,amountSol);this.store.updateTx(tx.id,{state:state.ok?'FETCH_STATE':'FAILED',error:state.ok?undefined:state.error});if(state.ok){this.store.updateTx(tx.id,{state:'BUILD'});this.store.updateTx(tx.id,{state:'SIMULATE'});const sim=await this.provider.simulateSolTransfer(from,destination,amountSol).catch((e:any)=>({err:e.message}));if(sim?.err||sim?.value?.err){this.store.updateTx(tx.id,{state:'FAILED',error:`Simulation failed: ${JSON.stringify(sim.err||sim.value.err)}`});throw new Error(`Simulation failed: ${JSON.stringify(sim.err||sim.value.err)}`)}this.store.updateTx(tx.id,{state:'RISK'});this.store.updateTx(tx.id,{state:'POLICY'});this.store.updateTx(tx.id,{state:'PREVIEW'});}if(!state.ok)throw new Error(state.error);return this.store.get().transactions.find(x=>x.id===tx.id)!}
 markAuthorization(id:string,approved:boolean,actor='wallet'){const t=this.store.get().transactions.find(x=>x.id===id);if(!t)throw new Error('Unknown transaction');if(t.state!=='PREVIEW'&&t.state!=='USER_AUTHORIZATION')throw new Error('Transaction is not awaiting authorization');this.store.updateTx(id,{state:approved?'USER_AUTHORIZATION':'FAILED',error:approved?undefined:'Authorization rejected'});this.store.audit('authorization',actor,'transaction',id,approved?'AUTHORIZED':'REJECTED');return this.store.get().transactions.find(x=>x.id===id)!}
}
